#include "dual_state_cuda_loss.cuh"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=2;c.d=3;c.s=2;c.m=2;c.e=4;c.vocab=261;CpuModel cpu(c);std::mt19937 rng(839);std::normal_distribution<float>d(0,.12f);for(auto&kv:cpu.w)for(auto&z:kv.second)z=kv.first.find("norm")!=std::string::npos?1.f:d(rng);TrainGraph graph(cpu);std::vector<Node>outputs;float loss=0;for(unsigned t:{17u,19u,23u})outputs.push_back(graph.step(t));loss+=seed_loss(outputs[0],19,false,.5f);for(float g:outputs[0]->grad.host())if(g!=0)throw std::runtime_error("masked seed");loss+=seed_loss(outputs[1],23,true,.5f);loss+=seed_loss(outputs[2],29,true,.5f);graph.tape.backward();auto objective=[&](){auto st=cpu.initial();double l=0;unsigned tokens[]={17,19,23},targets[]={19,23,29};for(int i=0;i<3;++i){auto y=cpu.step(tokens[i],st);if(i){double mx=*std::max_element(y.begin(),y.end()),sum=0;for(float z:y)sum+=std::exp(double(z)-mx);l+=(std::log(sum)+mx-y[targets[i]])*.5;}}return l;};double ref=objective(),worst=0;size_t count=0;if(std::abs(loss-ref)>2e-5)throw std::runtime_error("loss");for(auto&kv:cpu.w){auto g=graph.w.at(kv.first)->grad.host();for(size_t j=0;j<g.size();++j){float old=kv.second[j];kv.second[j]=old+.002f;double hi=kv.second[j],a=objective();kv.second[j]=old-.002f;double lo=kv.second[j],b=objective();kv.second[j]=old;double numeric=(a-b)/(hi-lo),err=std::abs(numeric-g[j]);if(!std::isfinite(err)||err>.006*(1+std::abs(numeric)))throw std::runtime_error("gradient");worst=std::max(worst,err);++count;}}auto eg=graph.w.at("embedding")->grad.host();double context=0;for(unsigned j=0;j<c.d;++j)context+=std::abs(eg[17*c.d+j]);printf("PASS multi-target mean_loss=%.7f params=%zu grad_max=%.9g shared_embedding_row17_grad=%.9g\n",loss,count,worst,context);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
